<section class="panel"><div class="panel-head"><div><h2>Checklist</h2><p>Track the task definition of done</p></div></div><div class="checklist-list"><?php foreach($related['checklists']??[] as $item):?><form method="post" action="<?= url('tasks/'.$record['id'].'/checklists/'.$item['id']) ?>"><?= csrf_field() ?><label><input type="checkbox" name="completed" value="1" <?= $item['is_completed']?'checked':'' ?> onchange="this.form.submit()"><span><?= e($item['item']) ?></span></label></form><?php endforeach;?><?php if(empty($related['checklists'])):?><div class="empty-inline">No checklist items.</div><?php endif;?></div><form class="mini-form inline-form" method="post" action="<?= url('tasks/'.$record['id'].'/checklists') ?>"><?= csrf_field() ?><input name="item" required maxlength="255" placeholder="New checklist item"><button class="button button-secondary button-sm">Add</button></form></section>
<section class="panel"><div class="panel-head"><div><h2>Time logs</h2><p><?= number_format(array_sum(array_column($related['time_logs']??[],'minutes'))/60,2) ?> total hours</p></div></div><div class="compact-list"><?php foreach(array_slice($related['time_logs']??[],0,8) as $log):?><div class="list-row"><span class="list-main"><strong><?= e($log['name']) ?> · <?= number_format($log['minutes']/60,2) ?>h</strong><small><?= e($log['note']?:'Work log') ?></small></span><span class="list-date"><?= e(date('d M',strtotime($log['work_date']))) ?></span></div><?php endforeach;?></div><form class="mini-form" method="post" action="<?= url('tasks/'.$record['id'].'/time-logs') ?>"><?= csrf_field() ?><div><input type="date" name="work_date" value="<?= date('Y-m-d') ?>" required><input type="number" name="minutes" min="1" max="1440" step="1" placeholder="Minutes" required></div><input name="note" maxlength="255" placeholder="Work performed"><button class="button button-secondary button-sm">Log time</button></form></section>
<section class="panel"><div class="panel-head"><div><h2>Update history</h2><p>Daily progress entries</p></div></div><div class="timeline-list"><?php foreach($related['updates']??[] as $item):?><div class="timeline-item"><span class="timeline-dot"></span><div><strong><?= e($item['name']) ?> · <?= (int)$item['progress'] ?>%</strong><p><?= e($item['update_text']) ?></p><small><?= e(date('d M, g:i A',strtotime($item['created_at']))) ?></small></div></div><?php endforeach;?><?php if(empty($related['updates'])):?><div class="empty-inline">No updates posted.</div><?php endif;?></div></section>
<section class="panel"><div class="panel-head"><div><h2>Task files</h2><p>Private attachments for assigned team members</p></div></div><div class="document-list"><?php foreach($related['files']??[] as $file):?><a href="<?= url('task-files/'.$file['id']) ?>"><i class="fa-solid fa-paperclip"></i><span><strong><?= e($file['original_name']) ?></strong><small><?= number_format($file['size_bytes']/1024,1) ?> KB</small></span><i class="fa-solid fa-download"></i></a><?php endforeach;?><?php if(empty($related['files'])):?><div class="empty-inline">No files uploaded.</div><?php endif;?></div><form class="mini-form inline-form" method="post" enctype="multipart/form-data" action="<?= url('tasks/'.$record['id'].'/files') ?>"><?= csrf_field() ?><input type="file" name="attachment" required accept=".jpg,.jpeg,.png,.webp,.pdf,.txt,.csv,.docx,.xlsx"><button class="button button-secondary button-sm">Upload securely</button></form></section>
